from __future__ import annotations

import inspect
from dataclasses import dataclass
from typing import Any

from ._source import scipy_integrate


@dataclass(frozen=True)
class SolverProfile:
    method: str
    use_analytic_jacobian: bool


PROFILES = {
    "automatic_stiff": SolverProfile(
        method="LSODA",
        use_analytic_jacobian=True,
    )
}


def _solver_classes() -> dict[str, Any]:
    """Initial-value solvers published by the bundled integrate namespace.

    The mapping is built by inspection instead of a fixed list so that every
    method the supplied source snapshot supports is available to a campaign.
    """
    integrate = scipy_integrate()
    base = getattr(integrate, "OdeSolver", None)
    solvers: dict[str, Any] = {}
    for name in dir(integrate):
        candidate = getattr(integrate, name, None)
        if not inspect.isclass(candidate):
            continue
        if base is None or not issubclass(candidate, base) or candidate is base:
            continue
        solvers[name] = candidate
    return solvers


def resolve_method_class(method: Any) -> Any | None:
    """Solver class behind a ``solve_ivp`` method, or ``None`` if unknown."""
    if inspect.isclass(method):
        return method
    if not isinstance(method, str):
        return None
    solvers = _solver_classes()
    if method in solvers:
        return solvers[method]
    for name, solver in solvers.items():
        if name.lower() == method.lower():
            return solver
    return None


def canonical_method_name(method: Any) -> str | None:
    """Spelling of ``method`` accepted by ``solve_ivp``, if it is supported."""
    if inspect.isclass(method):
        return None
    if not isinstance(method, str):
        return None
    for name in _solver_classes():
        if name.lower() == method.lower():
            return name
    return None


def accepts_analytic_jacobian(method: Any) -> bool:
    """Whether a solver method takes a user supplied Jacobian.

    Only the implicit methods expose a ``jac`` argument; passing one to an
    explicit method has no effect on the integration and is reported by the
    solver as an extraneous option, so a profile must be able to ask.
    """
    solver = resolve_method_class(method)
    if solver is None:
        return False
    try:
        parameters = inspect.signature(solver.__init__).parameters
    except (TypeError, ValueError):  # pragma: no cover - defensive
        return False
    return "jac" in parameters


def resolve_solver_profile(name: Any) -> SolverProfile:
    """Solver configuration named by a protocol.

    A protocol may reference a registered profile, carry a profile directly,
    or name any initial-value method supported by the bundled source.
    """
    if isinstance(name, SolverProfile):
        return name
    if isinstance(name, dict):
        return SolverProfile(**name)
    if inspect.isclass(name):
        return SolverProfile(
            method=name,
            use_analytic_jacobian=accepts_analytic_jacobian(name),
        )

    key = str(name)
    profile = PROFILES.get(key)
    if profile is not None:
        return profile

    method = canonical_method_name(key)
    if method is not None:
        return SolverProfile(
            method=method,
            use_analytic_jacobian=accepts_analytic_jacobian(method),
        )
    raise ValueError(f"unknown solver profile: {key}")
