"""Access to the bundled historical SciPy source snapshot."""

from __future__ import annotations

import sys
from pathlib import Path
from types import ModuleType


TASK_DIR = Path(__file__).resolve().parents[2]
SOURCE_DIR = TASK_DIR / "source"


def ensure_source_on_path() -> None:
    """Make the supplied source snapshot the imported implementation."""
    location = str(SOURCE_DIR)
    if location not in sys.path:
        sys.path.insert(0, location)


def scipy_integrate() -> ModuleType:
    """The integrate namespace of the supplied source snapshot."""
    ensure_source_on_path()
    from scipy import integrate

    return integrate
